  if(step==2){h='<h2>What sounds fun, '+PL_KN[plWizKid]+'?</h2><div class="facegrid">'+PL_INTENTS.map(([k,em,wd])=>'<button class="face" style="background:#111827;font-size:14px" onclick="plWizMood=\''+k+'\';plWiz(3)"><div style="font-size:34px">'+em+'</div>'+wd+'</button>').join("")+'</div>';}
  if(step==3){const r=PL_KLVL[plWizKid]||[1,3];h='<h2>How big a challenge?</h2><div class="facegrid" style="grid-template-columns:1fr">'+[[1,"● Easy peasy"],[2,"●● A real project"],[3,"●●● BIG challenge"]].map(([l,w])=>'<button class="face" style="background:'+(l>=r[0]&&l<=r[1]?"#e07b2a":"#d1d5db")+'" onclick="plWizLvl='+l+';plWizGo()">'+w+'</button>').join("")+'</div><div style="font-size:11px;color:var(--muted);text-align:center;margin-top:6px">orange = usually right for '+PL_KN[plWizKid]+'</div>';}
