  const free=plMaxOut(kid)-plOutCount(kid);
  let h='<h2>🧩 '+x.t+'</h2><div class="shloc">COMBO ×'+x.combo+' · for <span class="badge" style="background:'+PL_KC[kid]+'">'+PL_KN[kid]+'</span></div>';
